{
  "schemaVersion": "0.2",
  "slug": "link",
  "name": "Link",
  "status": "experimental",
  "purpose": "Navigates to another resource or anchor.",
  "scenarios": [
    "Navigate to a page",
    "Open an external reference",
    "Jump to an anchor"
  ],
  "props": {
    "children": {
      "type": "node",
      "required": true,
      "description": "Link text."
    },
    "href": {
      "type": "string",
      "required": true,
      "description": "Destination URL."
    },
    "external": {
      "type": "boolean",
      "required": false,
      "description": "Opens in a new tab and sets rel.",
      "default": false
    },
    "className": {
      "type": "string",
      "required": false,
      "description": "Additional CSS classes."
    }
  },
  "variants": [],
  "states": [
    {
      "name": "default",
      "description": "Link rendered."
    }
  ],
  "composition": {
    "allowedParents": [
      "text",
      "button",
      "card",
      "page"
    ],
    "allowedChildren": [
      "text",
      "icon"
    ],
    "requiredContext": []
  },
  "antiPatterns": [
    "Do not use a link for actions; use Button.",
    "Do not omit href for a clickable link."
  ],
  "a11y": {
    "role": "link",
    "keyboard": [
      "Tab focuses",
      "Enter activates"
    ],
    "focus": "Focus is visible.",
    "labeling": "Contents provide the accessible name.",
    "wcag": [
      "2.1.1",
      "2.4.4"
    ]
  },
  "responsive": {
    "strategy": "Inline.",
    "breakpoints": {
      "compact": "Inline.",
      "medium": "Inline.",
      "large": "Inline."
    }
  },
  "platforms": {
    "web": "supported",
    "react": "supported",
    "vue": "planned"
  },
  "rtl": {
    "supported": true,
    "strategy": "Logical CSS only.",
    "mirroredValues": []
  },
  "dataAi": {
    "role": "link",
    "states": [
      "default"
    ],
    "intents": [
      "navigate"
    ]
  }
}

import type { ReactNode } from 'react'
import './styles.css'

export interface LinkProps {
  children: ReactNode
  href: string
  external?: boolean
  className?: string
}

export function Link({ children, href, external = false, className }: LinkProps) {
  const classes = ['cu-link', className].filter(Boolean).join(' ')
  return (
    <a
      className={classes}
      data-ai-role="link" data-ai-state="default" data-ai-intent="navigate"
      href={href}
      rel={external ? 'noopener noreferrer' : undefined}
      target={external ? '_blank' : undefined}
    >
      {children}
    </a>
  )
}

.cu-link {
  color: var(--cu-color-palette-brand);
  text-decoration: underline;
  text-underline-offset: 0.15em;
}

/* Hover is gated so touch input never sticks in a hover style. */
@media (hover: hover) {
  .cu-link:hover {
    color: color-mix(in srgb, var(--cu-color-palette-brand) 80%, var(--cu-color-fg-default));
  }
}

.cu-link:focus-visible {
  outline: 3px solid var(--cu-color-palette-brand);
  outline-offset: 3px;
  border-radius: var(--cu-radius-sm);
}
